class Solution {
    public List<Integer> scrambledCopies(String text, String word) {
        int m = word.length();
        int[] need = new int[26];
        for (char c : word.toCharArray()) need[c - 'a']++;
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i + m <= text.length(); i++) {
            int[] have = new int[26];
            for (int j = i; j < i + m; j++) have[text.charAt(j) - 'a']++;
            if (Arrays.equals(have, need)) out.add(i);
        }
        return out;
    }
}

