class Solution:
    def scrambledCopies(self, text: str, word: str) -> List[int]:
        m = len(word)
        delta = [0] * 26
        for c in word:
            delta[ord(c) - 97] -= 1
        diff = sum(1 for d in delta if d)
        out = []

        def bump(x, by):
            nonlocal diff
            if delta[x] == 0:
                diff += 1
            delta[x] += by
            if delta[x] == 0:
                diff -= 1

        for i, c in enumerate(text):
            bump(ord(c) - 97, 1)
            if i >= m:
                bump(ord(text[i - m]) - 97, -1)
            if i >= m - 1 and diff == 0:
                out.append(i - m + 1)
        return out

