class Solution {
    private int[] delta = new int[26];
    private int diff = 0;

    private void bump(int x, int by) {
        if (delta[x] == 0) diff++;
        delta[x] += by;
        if (delta[x] == 0) diff--;
    }

    public List<Integer> scrambledCopies(String text, String word) {
        int m = word.length();
        for (char c : word.toCharArray()) bump(c - 'a', -1);
        List<Integer> out = new ArrayList<>();
        for (int i = 0; i < text.length(); i++) {
            bump(text.charAt(i) - 'a', 1);
            if (i >= m) bump(text.charAt(i - m) - 'a', -1);
            if (i >= m - 1 && diff == 0) out.add(i - m + 1);
        }
        return out;
    }
}

