        int m = word.size();
        for (char c : word) bump(c - 'a', -1);
        vector<int> out;
        for (int i = 0; i < (int) text.size(); i++) {
            bump(text[i] - 'a', 1);
            if (i >= m) bump(text[i - m] - 'a', -1);
            if (i >= m - 1 && diff == 0) out.push_back(i - m + 1);
        }
