};

code.c:
static void bump(int* delta, int* diff, int x, int by) {
    if (delta[x] == 0) (*diff)++;
    delta[x] += by;
    if (delta[x] == 0) (*diff)--;
}

int* scrambledCopies(char* text, char* word, int* returnSize) {
    int n = strlen(text), m = strlen(word), delta[26] = {0}, diff = 0, count = 0;
    for (int i = 0; i < m; i++) bump(delta, &diff, word[i] - 'a', -1);
    int* out = malloc((n + 1) * sizeof(int));
    for (int i = 0; i < n; i++) {
        bump(delta, &diff, text[i] - 'a', 1);
        if (i >= m) bump(delta, &diff, text[i - m] - 'a', -1);
        if (i >= m - 1 && diff == 0) out[count++] = i - m + 1;
    }
    *returnSize = count;
    return out;
}
